61	#define	pre_sign	VVAR(_pre_sign)
62	#define	r_sign		VVAR(_r_sign)
63	#define	r_z		VVAR(_r_z)
64	#define	r_bit		VVAR(_r_bit)
65	#define	last_bit	VVAR(_last_bit)
66	#define	r_dividend	VVAR(_r_dividend)
67	#define	r_divisor	VVAR(_r_divisor)
68	#define	vdiff		VVAR(_diff)
