73	#define	DIVASSERT(A) do { if (!(A)) { closetrace(); } assert(A); } while(0)
74	
75	class	DIV_TB : public TESTB<Vdiv> {
76	public:
77		DIV_TB(void) {
78		}
79	
80		~DIV_TB(void) {}
81	
82		void	reset(void) {
83			// m_flash.debug(false);
84			TESTB<Vdiv>::reset();
85		}
86	
87		void	bprint(char *str, int nbits, unsigned long v) {
88			while(*str)
89				str++;
90			for(int i=0; i<nbits; i++) {
91				if ((1l<<(nbits-1-i))&v)
92					*str++ = '1';
93				else
94					*str++ = '0';
95				if (((nbits-1-i)&3)==0)
96					*str++ = ' ';
97			} *str = '\0';
98		}
99	
100		void	dbgdump(void) {
101			char	outstr[2048], *s;
102			sprintf(outstr, "Tick %4lld %s%s%s%s%s%s%s %2d(%s= 0)",
103				(unsigned long long)m_tickcount,
104				(m_core->o_busy)?"B":" ",
105				(m_core->r_busy)?"R":" ",
106				(m_core->o_valid)?"V":" ",
107				(m_core->i_wr)?"W":" ",
108				(m_core->pre_sign)?"+":" ",
109				(m_core->r_sign)?"-":" ",
110				(m_core->r_z)?"Z":" ",
111				m_core->r_bit,
112				(m_core->last_bit)?"=":"!");
113			s = &outstr[strlen(outstr)];
114			sprintf(s, "\n%10s %40s", "Div","");
115				s = &s[strlen(s)];
116			bprint( s, 32, m_core->r_dividend);
117				s=&s[strlen(s)];
118			sprintf(s, "\n%10s ", "Div"); s = &s[strlen(s)];
119			bprint( s, 64, m_core->r_divisor);
120				s=&s[strlen(s)];
121			sprintf(s, "\n%10s %40s", "Q",""); s=&s[strlen(s)];
122			bprint( s, 32, m_core->o_quotient); s = &s[strlen(s)];
123			sprintf(s, "\n%10s %38s", "Diff","");
124				s=&s[strlen(s)];
125			bprint( s, 33, m_core->vdiff); s = &s[strlen(s)];
126			strcat(s, "\n");
127			puts(outstr);
128		}
129	
130		void	tick(void) {
131			bool	debug = false;
132	
133			if (debug)
134				dbgdump();
135			TESTB<Vdiv>::tick();
136		}
137	
138		void	divtest(uint32_t n, uint32_t d, uint32_t ans, bool issigned) {
139			const bool	dbg = false;
140	
141			// The test bench is supposed to assert that we are idle when
142			// we come in here.
143			DIVASSERT(m_core->o_busy == 0);
144	
145			// Request a divide
146			m_core->i_reset = 0;
147			m_core->i_wr = 1;
148			m_core->i_signed = (issigned)?1:0;
149			m_core->i_numerator = n;
150			m_core->i_denominator = d;
151	
152			// Tick once for the request to be registered
153			tick();
154	
155			// Clear the input lines.
156			m_core->i_wr = 0;
157			m_core->i_signed = 0;
158			m_core->i_numerator = 0;
159			m_core->i_denominator = 0;
160	
161			// Make certain busy is immediately true upon the first clock
162			// after we issue the divide, and that our result is not also
163			// listed as a valid result.
164			if (!m_core->o_busy) {
165				closetrace();
166				DIVASSERT(m_core->o_busy);
167			} if (m_core->o_valid != 0) {
168				closetrace();
169				DIVASSERT(m_core->o_valid == 0);
170			}
171	
172			// while((!m_core->o_valid)&&(!m_core->o_err))
173			while(!m_core->o_valid) {
174				// If we aren't yet valid, we'd better at least
175				// be busy--the CPU requires this.
176				if (!m_core->o_busy) {
177					// We aren't valid, and we aren't busy.  This
178					// is a test failure.
179					dbgdump();
180					closetrace();
181					DIVASSERT(m_core->o_busy);
182				}
183	
184				// Let the algorithm work for another clock tick.
185				tick();
186			} if (dbg) dbgdump();
187	
188			// Insist that the core not be busy any more, now that a valid
189			// result has been produced.
190			if (m_core->o_busy) {
191				closetrace();
192				DIVASSERT(!m_core->o_busy);
193			}
194	
195			if (dbg) {
196				printf("%s%s: %d / %d =? %d\n",
197					(m_core->o_valid)?"V":" ",
198					(m_core->o_err)?"E":" ",
199					n, d, m_core->o_quotient);
200			}
201	
202	
203			// Now that we're done, we need to check the result.
204			//
205			// First case to check: was there an error condition or, if not,
206			// should there have been one?
207			if (d == 0) {
208				// We attempted to divide by zero, the result should've
209				// been an error condition.  Let's check:
210				// Then insist on a division by zero error
211				if (!m_core->o_err) {
212					// Don't forget to close the trace before the
213					// assert, lest the file not get the final
214					// values into it.
215					closetrace();
216					DIVASSERT(m_core->o_err);
217				}
218			} else if (m_core->o_err) {
219				// Otherwise, there should not have been any divide
220				// errors.  The only errors allowed should be the
221				// divide by zero.  So, this is an error.  Let's
222				// stop and report it.
223				closetrace();
224				DIVASSERT(!m_core->o_err);
225			} else if (ans != (uint32_t)m_core->o_quotient) {
226				// The other problem we might encounter would be if the
227				// result doesn't match the one we are expecting.
228				//
229				// Stop on this bug as well.
230				//
231				closetrace();
232				DIVASSERT(ans == (uint32_t)m_core->o_quotient);
233			}
234	
235			if(((m_core->o_quotient == 0)&&((m_core->o_flags&1)==0))
236				||((m_core->o_quotient!= 0)&&((m_core->o_flags&1)!=0))){
237				fprintf(stderr, "Z-FLAG DOES NOT MATCH: FLAGS = %d, QUOTIENT = %08x\n", m_core->o_flags, m_core->o_quotient);
238				DIVASSERT((m_core->o_quotient!= 0)^(m_core->o_flags&1));
239			}
240		}
241	
242		// Test a signed divide
243		void	divs(int n, int d) {
244			int	ans;
245			// Calculate the answer we *should* get from the divide
246			ans = (d==0)?0:	(n / d);
247	
248			divtest((uint32_t)n, (uint32_t)d, (uint32_t)ans, true);
249		}
250	
251		// Test an unsigned divide
252		void	divu(unsigned n, unsigned d) {
253			unsigned	ans;
254	
255			// Pre-Calculate the answer we *should* get from the divide
256			ans = (d==0)?0:	(n / d);
257	
258			divtest((uint32_t)n, (uint32_t)d, (uint32_t)ans, false);
259		}
260	
261		// divide() is just another name for a signed divide--just switch to
262		// that function call instead.
263		void	divide(int n, int d) {
264			divs(n,d);
265		}
266	};
267	
268	//
269	// Standard usage functions.
270	//
271	// Notice that the test bench provides no options.  Everything is
272	// self-contained.
273	void	usage(void) {
274		printf("USAGE: div_tb\n");
275		printf("\n");
276		printf("\t\n");
277	}
278	
279	//
280	int	main(int argc, char **argv) {
281		// Setup
282		Verilated::commandArgs(argc, argv);
283		DIV_TB	*tb = new DIV_TB();
284	
285		/* Randomize the seed?
286		time_t	current_time;
287	
288		time(&current_time);
289		srand((unsigned int)current_time);
290		printf("Random seed: %08x\n", (unsigned int)current_time);
291		*/
292	
293		tb->reset();
294		tb->opentrace("div_tb.vcd");
295	
296		// Now we're ready.  All we need to do to test the divide of two
297		// numbers is to call the respective divide(), divs(), or divu()
298		// functions.  The program will crash on an assert error if anything
299		// goes wrong.
300		tb->divu((unsigned)-1,10);
301		tb->divide(125,7);
302		// And give us an extra clock tick in-between each test for good
303		// measure.
304		tb->tick();
305	
306		// Some other gentle tests
307		tb->divide(125,-7);
308		tb->tick();
309		tb->divu((1u<<31),7);
310		// Now some boundary conditions
311		tb->divu((7u<<29),(1u<<31));
312		tb->tick();
313		tb->divs(32768,0);
314		tb->tick();
315		tb->divu((1u<<31),0);
316		tb->tick();
317		tb->divs((1u<<30),0);
318		tb->tick();
319	
320		tb->divs( 15, 1); tb->tick();
321		tb->divs( 15,-1); tb->tick();
322		tb->divs(-15,-1); tb->tick();
323		tb->divs(-15, 1); tb->tick();
324	
325		tb->divs( 15, 4); tb->tick();
326		tb->divs( 15,-4); tb->tick();
327		tb->divs(-15,-4); tb->tick();
328		tb->divs(-15, 4); tb->tick();
329	
330		//
331		// Now we switch to a more thorough test set.  It's not complete, just
332		// ... more thorough.
333		for(int i=32767; i>=0; i--) {
334			tb->divs((1u<<30),i);
335			tb->tick();
336		} for(int i=32767; i>=0; i--) {
337			// tb->divu(-1, i);
338			tb->divu((1u<<31), i);
339			tb->tick();
340		} for(int i=32767; i>=0; i--) {
341			tb->divide(32768, i);
342			tb->tick();
343		}
344	
345		/*
346		 * While random data is a nice test idea, the following just never
347		 * really tested the divide unit thoroughly enough.
348		 *
349		tb->divide(rand(),rand()/2);
350		tb->tick();
351		tb->divide(rand(),rand()/2);
352		tb->tick();
353		tb->divide(rand(),rand()/2);
354		tb->tick();
355		tb->divide(rand(),rand()/2);
356		*/
357	
358		// Any failures above will be captured with a failed assert.  If we
359		// get here, it means things worked.  Close up shop ...
360		//
361		// This closes any potential trace file
362		delete	tb;
363	
364		// And declare success
365		printf("SUCCESS!\n");
366		exit(EXIT_SUCCESS);
367	}
368	
