370			m_state.m_sR[15] = m_core->cpu_ipc;
371			for(int i=0; i<16; i++)
372				m_state.m_uR[i] = m_core->cpu_regs[i+16];
373			m_state.m_uR[14] = (m_state.m_uR[14]&0xffffe000)|m_core->w_uflags;
374			m_state.m_uR[15] = m_core->cpu_upc;
375	
376			m_state.m_gie = m_core->r_gie;
377			m_state.m_pc  = (m_state.m_gie) ? (m_state.m_uR[15]):(m_state.m_sR[15]);
378			m_state.m_sp  = (m_state.m_gie) ? (m_state.m_uR[13]):(m_state.m_sR[13]);
379	
380	#ifdef	ZIPSYSTEM
381			// {{{
382			m_state.m_p[0] = m_core->pic_data;
383			m_state.m_p[1] = m_core->watchdog;
