399			m_state.m_p[10] = m_core->upc_data;
400			m_state.m_p[11] = m_core->uic_data;
401	
402			m_state.m_p[12] = m_core->mtc_data;
403			m_state.m_p[13] = m_core->moc_data;
404			m_state.m_p[14] = m_core->mpc_data;
405			m_state.m_p[15] = m_core->mic_data;
406			// }}}
407	#endif
