1543					0,
1544	#endif
1545					m_core->op_pc-4,
1546	#ifdef	OPT_CIS
1547					m_core->op_phase,
1548	#else
1549					false,
1550	#endif
1551					m_core->op_illegal);
1552				if (m_dbgfp) {
1553					fprintf(m_dbgfp, "\t\t\t(*OP=%d)[ A = 0x%08x , B = 0x%08x ], op_pc= %08x\n",
1554						m_core->op_opn,
