1740		void	wb_write(unsigned a, unsigned int v) {
1741			// {{{
1742			int	errcount = 0;
1743			if (m_dbgfp)
1744				fprintf(m_dbgfp, "WB-WRITE(%04x, %08x)\n", a, v);
1745			mvprintw(0,35, "%40s", "");
1746			mvprintw(0,40, "wb_write(%d,%x)", a, v);
1747			m_core->i_dbg_cyc = 1;
1748			m_core->i_dbg_stb = 1;
1749			m_core->i_dbg_we  = 1;
1750			m_core->i_dbg_sel = 15;
1751			m_core->i_dbg_addr = (a>>2);
1752			m_core->i_dbg_data = v;
1753	
1754			while((errcount++ < 100)&&(m_core->o_dbg_stall))
1755				tick();
1756			tick();
1757	
1758			m_core->i_dbg_stb = 0;
1759			while((errcount++ < 100)&&(!m_core->o_dbg_ack))
1760				tick();
1761	
1762			// Release the bus
1763			m_core->i_dbg_cyc = 0;
1764			m_core->i_dbg_stb = 0;
1765			tick();
1766			mvprintw(0,35, "%40s", "");
1767			mvprintw(0,40, "wb_write -- complete");
1768	
1769	
1770			if (errcount >= 100) {
1771				if (m_dbgfp) fprintf(m_dbgfp, "WB-WRITE: ERRCount = %d, BOMB!!\n", errcount);
1772				m_bomb = true;
1773			}
1774			// }}}
1775		}
