1971		void	execsim(const uint32_t imm) {
1972			// {{{
1973			uint32_t	*regp = m_core->cpu_regs;
1974			int		rbase;
1975			rbase = (m_core->r_gie)?16:0;
1976	
1977			if ((dbg_flag)&&(m_dbgfp)) {
1978				fprintf(m_dbgfp, "EXECSIM(0x%05x)\n", imm);
1979			}
1980	
1981			fflush(stdout);
1982			if ((imm & 0x03fffff)==0)
1983				// Ignore a NOOP
1984				return;
1985			// fprintf(stderr, "SIM-INSN(0x%08x)\n", imm);
1986			if ((imm & 0x0fffff)==0x00100) {
1987				// SIM Exit(0)
1988				// {{{
1989				m_rcode = 0;
1990				m_exit = true;
1991				if ((dbg_flag)&&(m_dbgfp))
1992					fprintf(m_dbgfp, "\tEXECSIM: SIM Exit(0)\n");
1993				// }}}
1994			} else if ((imm & 0x0ffff0)==0x00310) {
1995				// SIM Exit(User-Reg)
1996				// {{{
1997				int	rcode;
1998				rcode = regp[(imm&0x0f)+16] & 0x0ff;
1999				m_rcode = rcode;
2000				m_exit = true;
2001				if ((dbg_flag)&&(m_dbgfp))
2002					fprintf(m_dbgfp, "\tEXECSIM: SIM Exit(%d)\n", m_rcode);
2003				// }}}
2004			} else if ((imm & 0x0ffff0)==0x00300) {
2005				// SIM Exit(Reg)
2006				// {{{
2007				int	rcode;
2008				rcode = regp[(imm&0x0f)+rbase] & 0x0ff;
2009				m_rcode = rcode;
2010				m_exit = true;
2011				if ((dbg_flag)&&(m_dbgfp))
2012					fprintf(m_dbgfp, "\tEXECSIM: SIM Exit(%d)\n", m_rcode);
2013				// }}}
2014			} else if ((imm & 0x0fff00)==0x00100) {
2015				// SIM Exit(Imm)
2016				// {{{
2017				int	rcode;
2018				rcode = imm & 0x0ff;
2019				m_exit = true;
2020				m_rcode = rcode;
2021				if ((dbg_flag)&&(m_dbgfp))
2022					fprintf(m_dbgfp, "\tEXECSIM: SIM Exit(%d)\n", m_rcode);
2023				// }}}
2024			} else if ((imm & 0x0fffff)==0x002ff) {
2025				// Full/unconditional dump -- Now handled internally
2026				// {{{
2027				if (0 && m_console) {
2028					printf("SIM-DUMP\n");
2029					dump(regp);
2030				}
2031				// }}}
2032			} else if ((imm & 0x0ffff0)==0x00200) {
2033				// Dump a register -- Now handled internally
2034				// {{{
2035				if (0 && m_console) {
2036					int rid = (imm&0x0f)+rbase;
2037					//printf("%8lu @%08x R[%2d] = 0x%08x\n",
2038					//	m_time_ps/1000,
2039					//	m_core->cpu_ipc, rid, regp[rid]);
2040					printf("R[%2d] = 0x%08x\n", rid&0x0f,regp[rid]);
2041				}
2042				// }}}
2043			} else if ((imm & 0x0ffff0)==0x00210) {
2044				// Dump a user register -- Now handled internally
2045				// {{{
2046				if (0 && m_console) {
2047					int rid = (imm&0x0f);
2048					/*
2049					printf("%8lu @%08x uR[%2d] = 0x%08x\n",
2050						m_time_ps/1000, m_core->cpu_ipc,
2051						rid, regp[rid+16]);
2052					*/
2053					printf("uR[%2d] = 0x%08x\n",
2054						rid, regp[rid+16]);
2055				}
2056				// }}}
2057			} else if ((imm & 0x0ffff0)==0x00230) {
2058				// SOUT[User Reg] -- Handled internally
2059				// {{{
2060				if (0 && m_console) {
2061					int rid = (imm&0x0f)+16;
2062					printf("%c", regp[rid]&0x0ff);
2063				}
2064				// }}}
2065			} else if ((imm & 0x0fffe0)==0x00220) {
2066				// SOUT[User Reg] -- Handled internally
2067				// {{{
2068				if (0 && m_console) {
2069					int rid = (imm&0x0f)+rbase;
2070					printf("%c", regp[rid]&0x0ff);
2071				}
2072				// }}}
2073			} else if ((imm & 0x0fff00)==0x00400) {
2074				// SOUT[User Reg] -- Handled internally
2075				// {{{
2076				if (0 && m_console) {
2077					// SOUT[Imm]
2078					printf("%c", imm&0x0ff);
2079				}
2080				// }}}
2081			} else { // if ((insn & 0x0f7c00000)==0x77800000)
2082				if (m_console) {
2083					uint32_t	immv = imm & 0x03fffff;
2084					// Simm instruction that we dont recognize
2085					// if (imm)
2086					// printf("SIM 0x%08x\n", immv);
2087					printf("SIM 0x%08x (ipc = %08x, upc = %08x)\n", immv,
2088						m_core->cpu_ipc,
2089						m_core->cpu_upc);
2090				}
2091			} if (m_console)
2092				fflush(stdout);
2093			// }}}
2094		}
2095	};
