2097	
2098	// get_value
2099	// {{{
2100	void	get_value(ZIPCPU_TB *tb) {
2101		int	wy, wx, ra;
2102		int	c = tb->cursor();
2103	
2104		wx = (c & 0x03) * 20 + 9;
2105		wy = (c>>2);
2106		if (wy >= 3+4)
2107			wy++;
2108		if (wy > 3)
2109			wy += 2;
2110		wy++;
2111	
2112		if (c >= 12)
2113			ra = c - 12;
2114		else
2115			ra = c + 32;
2116	
2117		bool	done = false;
2118		char	str[16];
2119		int	pos = 0; str[pos] = '\0';
2120		while(!done) {
2121			int	chv = getch();
2122			switch(chv) {
2123			case KEY_ESCAPE:
2124				pos = 0; str[pos] = '\0'; done = true;
2125				break;
2126			case KEY_RETURN: case KEY_ENTER: case KEY_UP: case KEY_DOWN:
2127				done = true;
2128				break;
2129			case KEY_LEFT: case KEY_BACKSPACE:
2130				if (pos > 0) pos--;
2131				break;
2132			case CTRL('L'): redrawwin(stdscr); break;
2133			case KEY_CLEAR:
2134				pos = 0;
2135				break;
2136			case '0': case ' ': str[pos++] = '0'; break;
2137			case '1': str[pos++] = '1'; break;
2138			case '2': str[pos++] = '2'; break;
2139			case '3': str[pos++] = '3'; break;
2140			case '4': str[pos++] = '4'; break;
2141			case '5': str[pos++] = '5'; break;
2142			case '6': str[pos++] = '6'; break;
2143			case '7': str[pos++] = '7'; break;
2144			case '8': str[pos++] = '8'; break;
2145			case '9': str[pos++] = '9'; break;
2146			case 'A': case 'a': str[pos++] = 'A'; break;
2147			case 'B': case 'b': str[pos++] = 'B'; break;
2148			case 'C': case 'c': str[pos++] = 'C'; break;
2149			case 'D': case 'd': str[pos++] = 'D'; break;
2150			case 'E': case 'e': str[pos++] = 'E'; break;
2151			case 'F': case 'f': str[pos++] = 'F'; break;
2152			}
2153	
2154			if (pos > 8)
2155				pos = 8;
2156			str[pos] = '\0';
2157	
2158			attron(A_NORMAL | A_UNDERLINE);
2159			mvprintw(wy, wx, "%-8s", str);
2160			if (pos > 0) {
2161				attron(A_NORMAL | A_UNDERLINE | A_BLINK);
2162				mvprintw(wy, wx+pos-1, "%c", str[pos-1]);
2163			}
2164			attrset(A_NORMAL);
2165		}
2166	
2167		if (pos > 0) {
2168			int	v;
2169			v = strtoul(str, NULL, 16);
2170			if (!tb->halted()) { // Set the register
2171				// {{{
2172				tb->m_core->cpu_halt = 1;
2173				tb->wb_write(ra, v);
2174				tb->wb_write(CMD_REG, CMD_CATCH | CMD_GO);
2175				// }}}
2176			} else
2177				tb->cmd_write(ra, v);
2178		}
2179	}
2180	// }}}
2181	
2182	void	usage(void) {
2183		// {{{
2184		printf("USAGE: zippy_tb [-a] <testfile.out>\n");
2185		printf("\n");
2186		printf("\tWhere testfile.out is an output file from the assembler.\n");
2187		printf("\tThis file needs to be in a raw format and not an ELF\n");
2188		printf("\texecutable.  It will be inserted into memory at a memory\n");
2189		printf("\taddress of 0x0100000.  The memory device itself, the only\n");
2190		printf("\tdevice supported by this simulator, occupies addresses from\n");
2191		printf("\t0x0100000 to 0x01fffff.\n");
2192		printf("\n");
2193		printf("\t-a\tSets the testbench to run automatically without any\n");
2194		printf("\t\tuser interaction.\n");
2195		printf("\n");
2196		printf("\tUser Commands:\n");
2197		printf("\t\tWhen the test bench is run interactively, the following\n");
2198		printf("\t\tkey strokes are recognized:\n");
2199		printf("\t\t\'h\'\tHalt the processor using the external interface.\n");
2200		printf("\t\t\'g\'\tLet the processor run at full throttle with no.\n");
2201		printf("\t\t\tuser intervention.\n");
2202		printf("\t\t\'q\'\tQuit the simulation.\n");
2203		printf("\t\t\'r\'\tReset the processor.\n");
2204		printf("\t\t\'s\'\tStep the CPU using the external stepping command\n");
2205		printf("\t\t\tThis may consume more than one tick.\n");
2206		printf("\t\t\'t\'\tClock a single tick through the system.\n");
2207		// }}}
2208	}
2209	
2210	bool	signalled = false;
2211	
2212	void	sigint(int v) {
2213		signalled = true;
2214	}
2215	
2216	int	main(int argc, char **argv) {
2217		Verilated::commandArgs(argc, argv);
2218		ZIPCPU_TB	*tb = new ZIPCPU_TB();
2219		bool		autorun = false, exit_on_done = false, autostep=false;
2220		ZIPI		entry = RAMBASE;
2221	
2222		signal(SIGINT, sigint);
2223	
2224		if (argc <= 1) {
2225			// {{{
2226			usage();
2227			exit(-1);
2228			// }}}
2229		} else for(int argn=1; argn<argc; argn++) {
2230			// {{{
2231			if (argv[argn][0] == '-') {
2232				switch(argv[argn][1]) {
2233				case 'a':
2234					autorun = true;
2235					break;
2236				case 'e':
2237					exit_on_done = true;
2238					break;
2239				case 'h':
2240					usage();
2241					exit(0);
2242					break;
2243				case 's':
2244					autostep = true;
2245					break;
2246				default:
2247					usage();
2248					exit(-1);
2249					break;
2250				}
2251			} else if ((access(argv[argn], R_OK)==0)
2252						&&(iself(argv[argn]))) {
2253				ELFSECTION **secpp = NULL, *secp;
2254	
2255				elfread(argv[argn], entry, secpp);
2256	
2257				for(int i=0; secpp[i]->m_len; i++) {
2258					const char *data;
2259	
2260					secp = secpp[i];
2261					assert(secp->m_start >= RAMBASE);
2262					assert(secp->m_start+secp->m_len <= RAMBASE+RAMWORDS);
2263					assert((secp->m_len & 3)==0);
2264	
2265					data = &secp->m_data[0];
2266					tb->m_mem.load((secp->m_start-RAMBASE)>>2, data, secp->m_len);
2267				}
2268			} else {
2269				fprintf(stderr, "No access to %s, or unknown arg\n", argv[argn]);
2270				exit(-2);
2271			}
2272			// }}}
2273		}
2274	
2275	
2276		if (autorun) {
2277			// {{{
2278			bool	done = false;
2279	
2280			printf("Running in non-interactive mode\n");
2281			tb->m_console = true;
2282			tb->reset();
2283			// tb->m_core->cpu_halt = 1;
2284			tb->wb_write(CMD_REG, CMD_HALT|CMD_RESET|CMD_CATCH);
2285			tb->wb_write(CPU_sPC, entry);
2286			// Wait for the reset to release, leaving the CPU halted
2287			while(tb->wb_read(CMD_REG) & CMD_RESET)
2288				;
2289			// Then release the CPU
2290			tb->wb_write(CMD_REG, CMD_GO|CMD_CATCH);	// Release from halt and reset
2291			tb->m_bomb = false;
2292			while(!done) {
2293				tb->tick();
2294	
2295				/*
2296				printf("PC = %08x:%08x (%08x)\n",
2297					tb->m_core->cpu_ipc,
2298					tb->m_core->cpu_upc,
2299					tb->m_core->alu_pc);
2300				*/
2301	
2302				done = (tb->test_success())||(tb->test_failure());
2303				done = done || signalled;
2304			}
2305			// }}}
2306		} else if (autostep) {
2307			// {{{
2308			bool	done = false;
2309	
2310			printf("Running in non-interactive mode, via step commands\n");
2311			tb->m_console = true;
2312			tb->reset();
2313			tb->wb_write(CMD_REG, CMD_HALT|CMD_RESET|CMD_CATCH);
2314			tb->wb_write(CPU_sPC, entry);
2315			tb->wb_write(CMD_REG, CMD_GO|CMD_CATCH);	// Release from reset
2316			tb->m_bomb = false;
2317			while(!done) {
2318				tb->wb_write(CMD_REG, CMD_STEP|CMD_CATCH);
2319				/*
2320				printf("PC = %08x:%08x (%08x)\n",
2321					tb->m_core->cpu_ipc, tb->m_core->cpu_upc,
2322					tb->m_core->alu_pc);
2323				*/
2324				done = (tb->test_success())||(tb->test_failure());
2325				done = done || signalled;
2326			}
2327			// }}}
2328		} else { // Interactive
2329			// {{{
2330			initscr();
2331			raw();
2332			noecho();
2333			keypad(stdscr, true);
2334	
2335			tb->reset();
2336			tb->wb_write(CMD_REG, CMD_HALT|CMD_RESET|CMD_CATCH);
2337			tb->wb_write(CPU_sPC, entry);
2338			tb->wb_write(CMD_REG, CMD_GO|CMD_CATCH);	// Release from reset
2339	
2340			int	chv = 'q';
2341	
2342			bool	done = false, halted = true, manual = true,
2343				high_speed = false;
2344	
2345			halfdelay(1);
2346				// tb->show_state();
2347	
2348			while(!done) {
2349				// {{{
2350				if ((high_speed)&&(!manual)&&(!halted)) {
2351					// {{{
2352					// chv = getch();
2353	
2354					struct	pollfd	fds[1];
2355					fds[0].fd = STDIN_FILENO;
2356					fds[0].events = POLLIN;
2357	
2358					if (poll(fds, 1, 0) > 0)
2359						chv = getch();
2360					else
2361						chv = ERR;
2362					// }}}
2363				} else
2364					chv = getch();
2365	
2366				switch(chv) {
2367				// {{{
2368				case 'h': case 'H':
2369					tb->wb_write(CMD_REG, CMD_HALT|CMD_CATCH);
2370					if (!halted)
2371						erase();
2372					halted = true;
2373					break;
2374				case 'G':
2375					high_speed = true;
2376					// cbreak();
2377				case 'g':
2378					tb->wb_write(CMD_REG, CMD_GO|CMD_CATCH);
2379					if (halted)
2380						erase();
2381					halted = false;
2382					manual = false;
2383					break;
2384				case 'm':
2385					tb->show_user_timers(false);
2386					break;
2387				case 'q': case 'Q':
2388					done = true;
2389					break;
2390				case 'r': case 'R':
2391					if (manual)
2392						tb->reset();
2393					else
2394						tb->wb_write(CMD_REG, CMD_RESET|CMD_HALT|CMD_CATCH);
2395					halted = true;
2396					erase();
2397					break;
2398				case 's':
2399					if (!halted)
2400						erase();
2401					tb->step();
2402					manual = false;
2403					halted = true;
2404					// if (high_speed)
2405						// halfdelay(1);
2406					high_speed = false;
2407					break;
2408				case 'S':
2409					if ((!manual)||(halted))
2410						erase();
2411					manual = true;
2412					halted = true;
2413					// if (high_speed)
2414						// halfdelay(1);
2415					high_speed = false;
2416					tb->m_core->cpu_halt = 0;
2417					tb->m_core->cmd_step = 1;
2418					tb->eval();
2419					tb->tick();
2420					break;
2421				case 'T': //
2422					if ((!manual)||(halted))
2423						erase();
2424					manual = true;
2425					halted = true;
2426					// if (high_speed)
2427						// halfdelay(1);
2428					high_speed = false;
2429					tb->m_core->cpu_halt = 1;
2430					tb->m_core->cmd_step = 0;
2431					tb->eval();
2432					tb->tick();
2433					break;
2434				case 't':
2435					if ((!manual)||(halted))
2436						erase();
2437					manual = true;
2438					halted = false;
2439					// if (high_speed)
2440						// halfdelay(1);
2441					high_speed = false;
2442					tb->m_core->cpu_halt = 0;
2443					tb->tick();
2444					break;
2445				case 'u':
2446					tb->show_user_timers(true);
2447					break;
2448				case	KEY_IC: case KEY_ENTER: case KEY_RETURN:
2449					get_value(tb);
2450					break;
2451				case	KEY_UP:		tb->cursor_up();	break;
2452				case	KEY_DOWN:	tb->cursor_down();	break;
2453				case	KEY_LEFT:	tb->cursor_left();	break;
2454				case	KEY_RIGHT:	tb->cursor_right();	break;
2455				case CTRL('L'):	redrawwin(stdscr); break;
2456				case ERR: case KEY_CLEAR:
2457				default:
2458					if (!manual)
2459						tb->tick();
2460				// }}}
2461				}
2462	
2463				if (manual) {
2464					tb->show_state();
2465				} else if (halted) {
2466					if (tb->m_dbgfp)
2467						fprintf(tb->m_dbgfp, "\n\nREAD-STATE ******\n");
2468					tb->read_state();
2469				} else
2470					tb->show_state();
2471	
2472				if (tb->m_core->i_reset)
2473					done =true;
2474				if ((tb->m_bomb)||(signalled))
2475					done = true;
2476	
2477				if (exit_on_done) {
2478					if (tb->test_success())
2479						done = true;
2480					if (tb->test_failure())
2481						done = true;
2482				}
2483				// }}}
2484			}
2485			endwin();
2486			// }}}
2487		}
2488	#ifdef	MANUAL_STEPPING_MODE
2489		 else { // Manual stepping mode
2490			// {{{
2491			tb->jump_to(entry);
2492			tb->show_state();
2493	
2494			while('q' != tolower(chv = getch())) {
2495				// {{{
2496				tb->tick();
2497				tb->show_state();
2498	
2499				if (tb->test_success())
2500					break;
2501				else if (tb->test_failure())
2502					break;
2503				else if (signalled)
2504					break;
2505				// }}}
2506			}
2507			// }}}
2508		}
2509	#endif
2510	
2511		printf("\n");
2512		if (tb->test_failure()) {
2513			tb->dump_state();
2514		}
2515	
2516	#ifdef	ZIPSYSTEM
2517		printf("Clocks used         : %08x\n", tb->m_core->mtc_data);
2518		printf("Instructions Issued : %08x\n", tb->m_core->mic_data);
2519		printf("Tick Count          : %08lx\n", tb->m_tickcount);
2520		if (tb->m_core->mtc_data != 0)
2521			printf("Instructions / Clock: %.2f\n",
2522				(double)tb->m_core->mic_data
