39	#ifndef	TESTB_H
40	#define	TESTB_H
41	
42	#include <stdio.h>
43	#include <stdint.h>
44	#include <verilated_vcd_c.h>
45	
46	#define	TBASSERT(TB,A) do { if (!(A)) { (TB).closetrace(); } assert(A); } while(0);
47	
48	#ifdef	AXI_ACLK
49	#define	CLOCK	S_AXI_ACLK
50	#define	RESET	S_AXI_ARESETN
51	#else
52	#define	CLOCK	i_clk
53	#define	RESET	i_reset
54	#endif
55	
56	template <class VA>	class TESTB {
57	public:
58		VA		*m_core;
59		VerilatedVcdC*	m_trace;
60		uint64_t	m_tickcount;
61	
62		TESTB(void) : m_trace(NULL), m_tickcount(0l) {
63			m_core = new VA;
64			Verilated::traceEverOn(true);
65			m_core->CLOCK = 0;
66			eval(); // Get our initial values set properly.
67		}
68		virtual ~TESTB(void) {
69			closetrace();
70			delete m_core;
71			m_core = NULL;
72		}
73	
74		virtual	void	opentrace(const char *vcdname) {
75			if (!m_trace) {
76				m_trace = new VerilatedVcdC;
77				m_core->trace(m_trace, 99);
78				m_trace->open(vcdname);
79			}
80		}
81	
82		virtual	void	closetrace(void) {
83			if (m_trace) {
84				m_trace->close();
85				delete m_trace;
86				m_trace = NULL;
87			}
88		}
89	
90		virtual	void	eval(void) {
91			m_core->eval();
92		}
93	
94		virtual	void	tick(void) {
95			m_tickcount++;
96	
97			// Make sure we have our evaluations straight before the top
98			// of the clock.  This is necessary since some of the 
99			// connection modules may have made changes, for which some
100			// logic depends.  This forces that logic to be recalculated
101			// before the top of the clock.
102			eval();
103			if (m_trace) m_trace->dump((vluint64_t)(10*m_tickcount-2));
104			m_core->CLOCK = 1;
105			eval();
106			if (m_trace) m_trace->dump((vluint64_t)(10*m_tickcount));
107			m_core->CLOCK = 0;
108			eval();
109			if (m_trace) {
110				m_trace->dump((vluint64_t)(10*m_tickcount+5));
111				m_trace->flush();
112			}
113		}
114	
115		virtual	void	reset(void) {
116	#ifdef	AXI_ACLK
117			m_core->RESET = 0;
118			tick();
119			m_core->RESET = 1;
120	#else
121			m_core->i_reset = 1;
122			tick();
123			m_core->i_reset = 0;
124	#endif
125		}
126	
127		unsigned long	tickcount(void) {
128			return m_tickcount;
129		}
130	};
